class Solution:
    def countGoodSubsequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)
        f = [1] * (n + 1)
        for i in range(1, n + 1):
            f[i] = f[i-1] * i % MOD
        inv = [1] * (n + 1)
        inv[n] = pow(f[n], MOD - 2, MOD)
        for i in range(n, 0, -1):
            inv[i-1] = inv[i] * i % MOD
        def C(a, b):
            return f[a] * inv[b] % MOD * inv[a-b] % MOD
        from collections import Counter
        fs = list(Counter(s).values())
        ans = 0
        for L in range(1, max(fs) + 1):
            t = 1
            for x in fs:
                t = t * (C(x, L) + 1) % MOD
            ans = (ans + t - 1) % MOD
        return ans

