class Solution {
public:
    int countGoodSubsequences(string s) {
        const long long MOD = 1e9 + 7;
        int n = s.size();
        vector<long long> f(n + 1, 1), inv(n + 1, 1);
        for (int i = 1; i <= n; i++) f[i] = f[i-1] * i % MOD;
        inv[n] = pow(f[n], MOD - 2);
        for (int i = n; i >= 1; i--) inv[i-1] = inv[i] * i % MOD;
        auto C = [&](int a, int b) { return f[a] * inv[b] % MOD * inv[a-b] % MOD; };
        int cnt[26] = {0};
        for (char ch : s) cnt[ch - 'a']++;
        vector<int> fs;
        for (int i = 0; i < 26; i++) if (cnt[i]) fs.push_back(cnt[i]);
        long long ans = 0;
        for (int L = 1; L <= *max_element(fs.begin(), fs.end()); L++) {
            long long t = 1;
            for (int x : fs) t = t * (C(x, L) + 1) % MOD;
            ans = (ans + t - 1) % MOD;
        }
        return ans;
    }
    long long pow(long long b, long long e) {
        long long r = 1, m = 1e9 + 7;
        b %= m;
        while (e) { if (e & 1) r = r * b % m; b = b * b % m; e >>= 1; }
        return r;
    }
};

