class Solution {
    static final long MOD = 1_000_000_007L;
    public int countGoodSubsequences(String s) {
        int n = s.length();
        long[] f = new long[n + 1], inv = new long[n + 1];
        f[0] = 1;
        for (int i = 1; i <= n; i++) f[i] = f[i-1] * i % MOD;
        inv[n] = pow(f[n], MOD - 2);
        for (int i = n; i >= 1; i--) inv[i-1] = inv[i] * i % MOD;
        int[] cnt = new int[26];
        for (char ch : s.toCharArray()) cnt[ch - 'a']++;
        List<Integer> fs = new ArrayList<>();
        for (int c : cnt) if (c > 0) fs.add(c);
        long ans = 0;
        for (int L = 1; L <= Collections.max(fs); L++) {
            long t = 1;
            for (int x : fs) t = t * (comb(x, L, f, inv) + 1) % MOD;
            ans = (ans + t - 1) % MOD;
        }
        return (int) ans;
    }
    long comb(int a, int b, long[] f, long[] inv) {
        return f[a] * inv[b] % MOD * inv[a-b] % MOD;
    }
    long pow(long b, long e) {
        long r = 1;
        b %= MOD;
        while (e > 0) { if ((e & 1) == 1) r = r * b % MOD; b = b * b % MOD; e >>= 1; }
        return r;
    }
}

