var countGoodSubsequences = function(s) {
    const MOD = 1e9 + 7;
    const n = s.length;
    const f = new Array(n + 1).fill(1n), inv = new Array(n + 1).fill(1n);
    const B = BigInt(MOD);
    for (let i = 1; i <= n; i++) f[i] = f[i-1] * BigInt(i) % B;
    inv[n] = f[n] % B === 0n ? 0n : modPow(f[n], B - 2n, B);
    for (let i = n; i >= 1; i--) inv[i-1] = inv[i] * BigInt(i) % B;
    const cnt = {};
    for (const ch of s) cnt[ch] = (cnt[ch] || 0) + 1;
    const fs = Object.values(cnt);
    const C = (a, b) => f[a] * inv[b] % B * inv[a-b] % B;
    let ans = 0n;
    for (let L = 1; L <= Math.max(...fs); L++) {
        let t = 1n;
        for (const x of fs) t = t * (C(BigInt(x), BigInt(L)) + 1n) % B;
        ans = (ans + t - 1n) % B;
    }
    return Number(ans);
};
function modPow(b, e, m) { let r = 1n; b %= m; while (e > 0n) { if (e & 1n) r = r * b % m; b = b * b % m; e >>= 1n; } return r; }
